const filterBtns=document.querySelectorAll(".filter-btn"),pmItems=document.querySelectorAll(".pm-item");filterBtns.forEach(e=>{e.addEventListener("click",()=>{filterBtns.forEach(e=>e.classList.remove("active")),e.classList.add("active");const t=e.dataset.filter;pmItems.forEach(e=>{"all"===t||e.dataset.cat===t?(e.classList.remove("hidden"),e.style.animation="fadeInItem 0.4s ease forwards"):e.classList.add("hidden")})})});const lightbox=document.getElementById("lightbox"),lbImg=document.getElementById("lightbox-img"),lbCap=document.getElementById("lightbox-caption"),lbClose=document.getElementById("lightbox-close");function closeLightbox(){lightbox.classList.remove("open"),document.body.style.overflow=""}pmItems.forEach(e=>{e.addEventListener("click",()=>{const t=e.querySelector("img"),o=e.querySelector(".pm-overlay-cat").textContent;lbImg.src=t.src.replace("w=800","w=1200"),lbImg.alt=t.alt,lbCap.textContent=o,lightbox.classList.add("open"),document.body.style.overflow="hidden"})}),lbClose.addEventListener("click",closeLightbox),lightbox.addEventListener("click",e=>{e.target===lightbox&&closeLightbox()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&closeLightbox()}),document.addEventListener("DOMContentLoaded",()=>{const e=new URLSearchParams(window.location.search).get("category");if(e){const t=document.querySelector(`.portfolio-menu button[data-filter="${e}"]`)||document.querySelector(`.filter-btn[data-filter="${e}"]`);t&&(t.click(),t.scrollIntoView({behavior:"smooth",block:"center"}))}});